const shopifyOrder = input['iterate3A4G'][0]; 
const netsuiteOrder = input['netsuiteGetQuerySearchA2MM'][0];

function compareItems(shopifyItems, netsuiteItemsObj) {

  const netsuiteItems = Object.values(netsuiteItemsObj);

  const normalizedShopify = shopifyItems.map(i => ({
    sku: (i.sku || "").trim().toUpperCase(),
    shopifyId: i.id,
    quantity: Number(i.quantity || 0)
  }));

  const normalizedNetsuite = netsuiteItems
    .filter(n => n.itemDisplay)
    .map(n => ({
      raw: n.itemDisplay,
      sku: n.itemDisplay.trim().toUpperCase(),
      netsuiteId: n.item,
      quantity: Number(n.quantity || 0)
    }));

  const result = {
    shopifyNotInNetsuite: [],
    netsuiteNotInShopify: [],
    matched: [] 
  };

  // Shopify → NetSuite
  normalizedShopify.forEach(sItem => {

    const match = normalizedNetsuite.find(ns => ns.sku === sItem.sku);

    if (!match) {
      result.shopifyNotInNetsuite.push(sItem.sku);
    } else {
      result.matched.push({
        sku: sItem.sku,
        shopifyId: sItem.shopifyId,
        netsuiteId: match.netsuiteId,
        shopifyQty: sItem.quantity,
        netsuiteQty: match.quantity
      });
    }

  });

  // NetSuite → Shopify
  normalizedNetsuite.forEach(ns => {
    const found = normalizedShopify.some(s => s.sku === ns.sku);
    if (!found) result.netsuiteNotInShopify.push(ns.raw);
  });

  return result;
}

return compareItems(
  shopifyOrder.lineItems, 
  netsuiteOrder.sublists.item
);
